from cards_a import card
card(slug="brownstone-2024-ifs-problematic-popularity", title="Brownstone et al. 2024 - IFS: exploring its problematic popularity",
 cite='Brownstone LM et al. "Internal Family Systems: Exploring Its Problematic Popularity." Society for the Advancement of Psychotherapy (societyforpsychotherapy.org). June 26, 2024.',
 url="https://societyforpsychotherapy.org/internal-family-systems-exploring-its-problematic-popularity/",
 level="7 (expert critical commentary; cites trial literature)", area="IFS / parts language - evidence critique",
 s=[6,4,8,8,6,7,6,8,6,9],
 j=["Authors are licensed-psychologist academics writing in an APA-division (Society for the Advancement of Psychotherapy) venue; editorial, not peer-reviewed article.",
   "Commentary; counts three supportive studies and cites a count of Psychology Today listings; relies partly on authors' clinical observations.","June 2024.",
   "Professional field advancement / harm-prevention.","One-sided by design (a critique) but acknowledges the supporting studies exist.","Argues scale of use outpaces evidence; sound.",
   "Corroborated by 2025 scoping review headline reported in search results (Taylor & Francis, 403 on fetch; not verified here).",
   "Concedes some trial support exists.","Names studies and the 45,764 therapist count.","Direct falsification-side evidence on IFS."],
 bias="neutral",
 findings=["IFS has a 'strikingly small' evidence base for a 30-year-old model: three studies cited (depression, RA pain, PTSD, dissociation).",
   "Authors argue current expansion of IFS use has 'moved beyond its evidence base'; excluded populations (e.g. psychosis) and possible harms noted.",
   "Evidence for IFS tests the therapy package, not whether 'parts' language itself is the active ingredient.",
   "Popularity metric: 45,764 Psychology Today therapists mentioned IFS as of April 2024."],
 quotes=["Notably, there is a strikingly small evidence-base in the literature for IFS, particularly given that it was developed 30 years ago.",
   "We believe that the current expansion of IFS across psychotherapy and social media has moved beyond its evidence base."],
 qfile="ifscrit.txt", loc="Body, paragraph on evidence base (second section) and heading 'Potential Harms of the Overapplication of Internal Family Systems', first paragraph.", access="live",
 dec="Core", rat="Best accessible falsification source on IFS; Contrarian category requirement. Commentary rather than data - weight accordingly.",
 red="No other located fetchable source states the IFS critique; the 2025 T&F scoping review was blocked (403).", persp="Contrarian")

card(slug="shadick-2013-ifs-ra-rct", title="Shadick et al. 2013 - IFS RCT in rheumatoid arthritis",
 cite='Shadick NA, Sowell NF, Frits ML, Hoffman SM, et al. "A Randomized Controlled Trial of an Internal Family Systems-based Psychotherapeutic Intervention on Outcomes in Rheumatoid Arthritis: A Proof-of-Concept Study." Journal of Rheumatology. 2013. DOI 10.3899/jrheum.121465 (abstract snapshot via scholarly adapter).',
 url="https://doi.org/10.3899/jrheum.121465",
 level="2 (proof-of-concept RCT, N=79 randomised)", area="IFS / parts language - trial evidence",
 s=[8,6,4,9,7,8,5,9,9,5],
 j=["Brigham and Women's Hospital rheumatology group; peer-reviewed J Rheumatol.","RCT with blinded rheumatologist assessment but N=79, attention-control by mailed materials, many outcomes, p-values around 0.04.",
   "2013.","Clinical research.","Reports sustained vs not-sustained outcomes plainly.","Sound proof-of-concept framing.","One of only three IFS studies Brownstone 2024 names.","Concludes only 'feasible and acceptable', 'future efficacy trials are warranted'.",
   "Gives n, p, effect sizes.","Tests IFS as a package on RA pain, not parts-naming as a work or emotion tool: indirect."],
 bias="neutral",
 findings=["Randomised 79 RA patients to 9 months of IFS group vs an education control; 68 completed assessments.",
   "Post-treatment gains in overall pain and physical function (both p = 0.04); sustained at one year for joint pain, self-compassion, depressive symptoms.",
   "No sustained improvement in anxiety, self-efficacy, or (blinded) disease activity.",
   "Authors conclude only feasibility/acceptability and that efficacy trials are needed."],
 quotes=["There were no sustained improvements in anxiety, self-efficacy, or disease activity.",
   "An IFS-based intervention is feasible and acceptable to patients with RA and may complement medical management of the disease. Future efficacy trials are warranted."],
 qfile="ADAPTER:c2-naming-01-a-randomized-controlled-trial-of-an-internal-fam.txt", loc="Abstract snapshot, RESULTS (last sentence) and CONCLUSION.", access="cached/partial",
 dec="Supporting", rat="Gives the best-controlled IFS trial evidence located; Supporting because outcome is RA pain/psych status in a package, not naming-of-parts per se.",
 red="Complements Brownstone 2024 by showing what the 'some support' consists of.", persp="Academic")

card(slug="dulwich-centre-what-is-narrative-therapy", title="Dulwich Centre - What is narrative therapy?",
 cite='Dulwich Centre. "What is Narrative Therapy?" (extract from Alice Morgan, What is narrative therapy? An easy-to-read introduction). dulwichcentre.com.au. Accessed 2026-10-03.',
 url="https://dulwichcentre.com.au/what-is-narrative-therapy/",
 level="7 (practitioner/expert statement from the originating institute; no outcome data on this page)", area="Externalization / 'the problem is the problem'",
 s=[6,2,6,4,3,6,5,5,4,7],
 j=["Dulwich Centre is the training and publishing home of White and Epston's narrative approach; credible on what the model says, not whether it works.",
   "Definition page; no outcome evidence. Dulwich links to separate evidence collections not assessed here.","Page in current state; extract from a popular book.",
   "Training/publishing organisation promoting the approach; sells books and courses.","Advocacy tone, no counter-evidence.","Coherent description.",
   "Consistent with Kross 2017 self-distancing mechanism conceptually.","Does not discuss limits of externalization.","Qualitative definitions only.","Defines the externalizing premise ('problems are separate from people')."],
 bias="neutral",
 findings=["Narrative therapy 'views problems as separate from people' - the core externalization premise.",
   "It assumes people have skills, beliefs, values and commitments that reduce 'the influence of problems in their lives'.",
   "Frames person as expert in own life; questions asked from genuine curiosity.",
   "No effect-size evidence on this page; evidence for externalization per se is thin (Hu 2024 meta-analysis rejected - very low GRADE, not about externalization specifically)."],
 quotes=["It views problems as separate from people and assumes people have many skills, competencies, beliefs, values, commitments and abilities that will assist them to reduce the influence of problems in their lives."],
 qfile="dul.txt", loc="Opening paragraph under heading 'What is Narrative Therapy?' (also repeated in 'Summary').", access="live",
 dec="Supporting", rat="Primary-institution statement of the externalization premise (White's 'problem is the problem'); evidence quality is deliberately scored low. Borderline-to-keep on the band; kept as the only Practitioner source defining externalization.",
 red="No stronger source states the premise from the originating school; efficacy evidence is a gap.", persp="Practitioner")

card(slug="kross-2017-third-person-self-talk", title="Moser et al. 2017 - third-person self-talk (self-distancing)",
 cite='Moser JS, Dougherty A, Mattson WI, Katz B, Moran TP, Guevarra D, Shablack H, Ayduk O, Jonides J, Berman MG, Kross E. "Third-person self-talk facilitates emotion regulation without engaging cognitive control: Converging evidence from ERP and fMRI." Scientific Reports 7:4519. 2017. PMC5495792.',
 url="https://pmc.ncbi.nlm.nih.gov/articles/PMC5495792/",
 level="3 (two within-subject neuroimaging experiments)", area="Externalization mechanism - psychological distance",
 s=[8,6,5,9,8,7,6,7,8,6],
 j=["Michigan/Kross lab (self-distancing originators), peer-reviewed Scientific Reports.","ERP and fMRI converging evidence but small samples and lab tasks.","2017.","Academic.","Originating lab.","Sound.",
   "Part of a self-distancing literature (Kross & Ayduk), replications mixed in applied settings (not fetched).","Uses 'may constitute'.","Names markers (LPP, SPN, mPFC).","Closest tested mechanism for 'talk about the problem as an it/he' externalization; indirect for work states."],
 bias="neutral",
 findings=["Silent third-person self-talk reduced a neural marker of self-referential emotional reactivity (late positive potential) within the first second.",
   "fMRI Study 2: lower medial prefrontal cortex (self-referential) activation when reflecting on negative memories in third person.",
   "No increase in cognitive-control markers - described as a relatively effortless form of self-control.",
   "Mechanism: psychological distance, the plausible active ingredient behind externalization (problem-as-object)."],
 quotes=["Together, these results suggest that third-person self-talk may constitute a relatively effortless form of self-control."],
 qfile="kross.txt", loc="Abstract (PMC page), final sentence.", access="live",
 dec="Supporting", rat="Gives a tested psychological-distance mechanism for externalization; Supporting because it tests pronouns, not 'parts' or problem-naming directly.",
 red="No other located source tests a distance mechanism.", persp="Academic")

card(slug="aan-willcox-feeling-wheel", title="Alexithymia Awareness Network - Gloria Willcox and the Feeling Wheel",
 cite='Alexithymia Awareness Network. "Gloria Willcox and the Feeling Wheel." alexithymiaawarenessnetwork.org/wilcox. Accessed 2026-10-03. Refers to Willcox G. "The Feeling Wheel: A Tool for Expanding Awareness of Emotions and Increasing Spontaneity and Intimacy." Transactional Analysis Journal 12(4):274-276. 1982. DOI 10.1177/036215378201200411 (not fetched; paywalled).',
 url="https://alexithymiaawarenessnetwork.org/wilcox/",
 level="7 (organisation's cautious profile; confirms origin, states no effectiveness evidence)", area="Feeling wheel origin and evaluation",
 s=[5,3,8,7,8,8,6,10,6,9],
 j=["Alexithymia-awareness organisation; not a primary or academic source on the wheel.","Descriptive; no outcome studies.","Page current.","Public education.","Balanced and cautionary.","Clear.",
   "Origin facts (TAJ 1982, vol 12) corroborated by Semantic Scholar/search listings.","Explicitly says page 'does not establish' effectiveness; no evaluation of the wheel is cited.","Gives citation, uses.","Directly states what a feeling wheel is for and its limits."],
 bias="neutral",
 findings=["The Feeling Wheel is a 1982 Transactional Analysis Journal article by Gloria Willcox.",
   "Framed as a vocabulary scaffold that lets a person move from broad categories toward more specific words.",
   "The page states the wheel is not a diagnosis, measure, treatment or proof of a fixed emotion structure.",
   "The page itself makes no effectiveness claim - and I found no published effectiveness evaluation of the Willcox wheel (gap)."],
 quotes=["It should not be treated as a diagnosis, a measure of alexithymia, a treatment, or proof that emotions have one fixed structure.",
   "This page does not establish a full biography, affiliation, licensing, therapeutic specialty, reach, or effectiveness claim."],
 qfile="wilcox.txt", loc="Page body, paragraph 'Why Willcox appears on AAN' (first quote) and 'Do not infer' paragraph (second quote).", access="live",
 dec="Supporting", rat="Used to document the wheel's origin and, importantly, the ABSENCE of effectiveness evidence; low evidence quality but honest and cautious. Weak keep; named as marginal.",
 red="No academic source evaluating the wheel found.", persp="Practitioner")

card(slug="ford-parnin-2015-frustration-categories", title="Ford & Parnin 2015 - causes of frustration for developers",
 cite='Ford D, Parnin C. "Exploring Causes of Frustration for Software Developers." CHASE 2015 (8th IEEE/ACM Int. Workshop on Cooperative and Human Aspects of Software Engineering). 2015.',
 url="https://denaeford.me/papers/developer-frustration-CHASE-2015.pdf",
 level="6 (qualitative survey, n=45, open card sort)", area="Work-state analogue - naming 'stuck/frustrated' states",
 s=[7,4,3,8,7,7,5,7,7,7],
 j=["NC State HCI/SE researchers, peer-reviewed workshop paper.","n=45 self-selected, card sort by two authors; no validity testing.","2015, pre-LLM tooling; timeless bonus for human frustration causes.","Research.","Acknowledges it is a first step toward a framework.","Open card sort is a legitimate taxonomy-building method.",
 "Builds on Ko et al. 2004 barriers; consistent with later Ford/Parnin follow-ups (not fetched).","States it is the start of a framework.","Gives n and 67% severity.","Shows developers can name frustration causes into a small closed set (11) - an analogue for naming 'stuck'."],
 bias="neutral",
 findings=["67% of 45 developers rated their most recent frustration as severe.",
   "Open card sort of recalled experiences converged on 11 cause categories (e.g. mapping behavior to code, broken tools).",
   "Authors explicitly propose a common framework as the basis for interventions - the closest located precedent for a fixed vocabulary of 'stuck' causes.",
   "No test of whether SHOWING developers the vocabulary changes outcomes."],
 quotes=["Defining a common framework that explains why these experiences occur can lead to better interventions and learning mechanisms.",
   "Further, we distilled the reported experiences into 11 categories, which include issues with mapping behaviors to code and broken programming tools."],
 qfile="ford.txt", loc="Abstract (p.1).", access="live",
 dec="Supporting", rat="Best located empirical precedent for a closed taxonomy of developer 'stuck' states; evidence is descriptive only.",
 red="Complements Ko 2004 (learning barriers) with a post-hoc frustration taxonomy.", persp="Academic")

card(slug="ko-myers-aung-2004-learning-barriers", title="Ko, Myers & Aung 2004 - six learning barriers",
 cite='Ko AJ, Myers BA, Aung HH. "Six Learning Barriers in End-User Programming Systems." IEEE Symposium on Visual Languages and Human-Centric Computing (VL/HCC). 2004.',
 url="https://faculty.washington.edu/ajko/papers/Ko2004LearningBarriers.pdf",
 level="6 (qualitative observational study of beginning programmers)", area="Work-state analogue - a fixed vocabulary for 'stuck'",
 s=[7,4,2,8,8,7,6,6,6,7],
 j=["CMU HCI researchers, peer-reviewed IEEE symposium; Ko is a leading programming-education researcher.","Observational study of beginners in one system (Visual Basic.NET).","2004; pre-2020 but taxonomy is conceptual (timeless bonus).",
   "Research.","Descriptive.","Clear barrier types.","Frequently built on (cited by Ford & Parnin 2015).","Standard limits for a qualitative study.","Names six barrier types and gives examples.","Concrete, named taxonomy of WHERE a programmer is stuck."],
 bias="neutral",
 findings=["Observed beginners learning Visual Basic.NET; identified six barrier types: design, selection, coordination, use, understanding, information.",
   "Each name points at a different remedy (e.g. selection = which tool/API to use; coordination = how pieces combine).",
   "Treats 'stuck' as a typed event rather than one lump.",
   "Taxonomy was derived from observation of one population; not a validated instrument."],
 quotes=["This identified six types of barriers: design, selection, coordination, use, understanding, and information."],
 qfile="ko.txt", loc="Abstract (p.1).", access="live",
 dec="Supporting", rat="Foundational typed vocabulary for stuck-ness that maps onto workflow tool design; old and narrow, hence Supporting.",
 red="Pairs with Ford & Parnin 2015.", persp="Academic")

card(slug="substack-2026-audhd-alexithymia", title="carmen_authenticallyadhd 2026 - AuDHD, alexithymia, 'feelings but no captions'",
 cite='carmen_authenticallyadhd. "AuDHD, Alexithymia, and Anhedonia: When Your Brain Has Feelings... But No Captions (and the Joy Volume Is Turned Down)." Substack. Jan 31, 2026 (paid post; preview/body partially visible).',
 url="https://carmenauthenticallyadhd.substack.com/p/audhd-alexithymia-and-anhedonia-when",
 level="8 (practitioner/lived-experience blog post with secondary research citations)", area="ADHD and naming - lived experience",
 s=[3,2,10,6,6,5,4,4,4,7],
 j=["Anonymous-ish ADHD creator; qualifications not verifiable.","No primary citations on the page for the numbers quoted.","Jan 2026.","Education/audience-building on a paid newsletter.","Sympathetic, one-sided.","Mixed.","Overlaps with other ADHD-alexithymia write-ups found in search (neurodivergentinsights, simplypsychology), none verified.","Some hedging ('Research suggests').","Specific lay descriptions only.","Shows how ADHD-community content frames 'feelings without captions'."],
 bias="neutral",
 findings=["Describes alexithymia as trouble identifying/describing feelings; 'your body may be broadcasting emotion... but your brain is struggling to translate the signal into words'.",
   "Frames emotions arriving as 'mystery symptoms', surprise explosions or shutdowns when labels are missing.",
   "Offers journaling prompts rather than a fixed vocabulary.",
   "Illustrative of the audience problem (unnamed states), not of any tool's efficacy."],
 quotes=["In plain language: your body may be broadcasting emotion… but your brain is struggling to translate the signal into words."],
 qfile="sub.txt", loc="Section 'What is alexithymia?' (first paragraph after bullet list).", access="live",
 dec="Supporting", rat="Borderline on score band; kept ONLY as the sole Boots-on-the-ground voice and to show the ADHD-community framing of unnamed states. Do not use for empirical claims.",
 red="No stronger lived-experience source located in budget; quantitative ADHD-alexithymia claims need a primary source (gap).", persp="Boots-on-the-ground")

card(slug="shimmer-2024-naming-feelings-adhd", title="Shimmer ADHD Coaching 2024 - Can naming your feelings help ADHD?",
 cite='Mulholland T (NBC-HWC). "Can naming your feelings help ADHD?" Shimmer ADHD Coaching blog (shimmer.care). Sept 20, 2024.',
 url="https://www.shimmer.care/blog/can-naming-your-feelings-help-adhd",
 level="9 (commercial coaching-company content marketing)", area="ADHD and naming - practitioner framing of feelings wheel",
 s=[4,2,7,3,3,4,4,3,4,8],
 j=["Board-certified health & wellness coach writing for a coaching company; not a clinician-researcher.","No citations for the claims that naming lowers intensity or helps impulsivity.","Sept 2024.",
   "Content marketing for a paid ADHD coaching product.","Presents benefits only.","Reasoning leans on the 'naming lowers intensity' assumption, which Nook 2021 / Ariely 2026 complicate.",
   "Echoes common wellness-site claims; contradicted in part by experimental literature.","No limits stated.","Gives a 7-step procedure, but no data.","On-topic: ADHD + feelings wheel + vocabulary."],
 bias="neutral",
 findings=["Describes the feelings wheel as three tiers: primary, second-tier, third-tier, moving from the center outward.",
   "Claims naming feelings lessens overwhelm, impulsivity and intensity for ADHDers - asserted without evidence; compare Nook 2021.",
   "Notes 'different models of the Feelings Wheel... same basic themes'.",
   "Recommends keeping the wheel visible (print, fridge, phone) and a 7-step check-in."],
 quotes=["Naming feelings lowers the intensity of emotions, so you can respond in a flexible and measured way.",
   "There are different models of the Feelings Wheel, with various names of feelings, but the same basic themes are found in each model."],
 qfile="shim.txt", loc="Section 'Benefits of naming feelings for ADHD' (Emotional Regulation bullet) and section 'What is a feelings wheel?' (final sentence of the second paragraph).", access="live",
 dec="Excluded", rat="Reject band. Retained as a card only to document the practitioner-layer OVERCLAIM (unqualified 'naming lowers intensity') that the experimental literature does not support unconditionally. Do not cite for effect.",
 red="Superseded by Torre & Lieberman 2018 + Nook 2021 for the real claim.", persp="Practitioner")
